<?php
namespace App\Http\Controllers\Api\V1;
use App\Models\{AccountingCurrency,Branch,Company,Customer,CustomerContact,Opportunity,ProductVariant,SalesOrder,SalesOrderItem,SalesPriceList,SalesPriceListItem,SalesQuotation,SalesQuotationApproval,SalesQuotationCommunication,SalesQuotationItem,SalesQuotationResponse,SalesQuotationVersion,TaxConfiguration};
use App\Jobs\SendSalesQuotationEmail; use App\Services\{AuditLogger,AuthorizationService,SalesNumberService}; use App\Support\{Decimal,TenantContext}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Validation\Rule; use Illuminate\Validation\ValidationException;
final class SalesQuotationController {
 private function t():string{return app(TenantContext::class)->id();} private function own(SalesQuotation $q):void{abort_unless($q->tenant_id===$this->t(),404);} private function auth(Request $r,string $p,?string $c=null,?string $b=null):void{abort_unless(app(AuthorizationService::class)->allows($r->user(),$this->t(),$p,$c,$b),403);} private function scope(Request $r,string $c,?string $b=null):void{$this->auth($r,'sales.manage',$c,$b);abort_unless(Company::where('tenant_id',$this->t())->whereKey($c)->where('is_active',true)->exists(),422,'Company is unavailable.');if($b)abort_unless(Branch::where('tenant_id',$this->t())->where('company_id',$c)->whereKey($b)->where('is_active',true)->exists(),422,'Branch is unavailable.');}
 private function audit(Request $r,string $action,SalesQuotation $q):void{app(AuditLogger::class)->record($r,$action,$this->t(),$q,['company_id'=>$q->company_id,'state'=>$q->state,'approval_status'=>$q->approval_status,'response_status'=>$q->response_status]);}
 private function input(Request $r):array{return $r->validate(['company_id'=>'required|uuid','branch_id'=>'nullable|uuid','customer_id'=>'required|uuid','customer_contact_id'=>'nullable|uuid','opportunity_id'=>'nullable|uuid','assigned_salesperson_id'=>'nullable|uuid','currency_id'=>'nullable|uuid','price_list_id'=>'nullable|uuid','quotation_date'=>'nullable|date','valid_until'=>'nullable|date|after_or_equal:quotation_date','customer_reference'=>'nullable|string|max:120','payment_terms'=>'nullable|string','delivery_terms'=>'nullable|string','terms_and_conditions'=>'nullable|string','customer_notes'=>'nullable|string','internal_notes'=>'nullable|string','additional_charges'=>'nullable|numeric|min:0','items'=>'required|array|min:1','items.*.variant_id'=>'required|uuid','items.*.description'=>'nullable|string|max:500','items.*.unit'=>'nullable|string|max:40','items.*.quantity'=>'required|numeric|gt:0','items.*.unit_price'=>'nullable|numeric|min:0','items.*.discount_type'=>['nullable',Rule::in(['percentage','fixed'])],'items.*.discount_rate'=>'nullable|numeric|min:0|max:100','items.*.discount_amount'=>'nullable|numeric|min:0','items.*.tax_code'=>'nullable|string|max:50','items.*.tax_rate'=>'nullable|numeric|min:0|max:100']);}
 private function lines(array $d,string $company):array{$out=[];foreach($d['items'] as $i){$v=ProductVariant::where('tenant_id',$this->t())->with('product')->findOrFail($i['variant_id']);$rate=(string)($i['tax_rate']??0);if(!empty($i['tax_code']))$rate=(string)TaxConfiguration::where('tenant_id',$this->t())->where('company_id',$company)->where('code',$i['tax_code'])->where('is_active',true)->firstOrFail()->rate;$price=(string)($i['unit_price']??$v->price);if(!empty($d['price_list_id'])){$list=SalesPriceList::where('tenant_id',$this->t())->where('company_id',$company)->whereKey($d['price_list_id'])->where('is_active',true)->firstOrFail();$rule=SalesPriceListItem::where('tenant_id',$this->t())->where('price_list_id',$list->id)->where('variant_id',$v->id)->where('minimum_quantity','<=',(string)$i['quantity'])->orderByDesc('minimum_quantity')->first();if($rule)$price=(string)$rule->unit_price;}$sub=Decimal::mul((string)$i['quantity'],$price);$disc=($i['discount_type']??'percentage')==='fixed'?(string)($i['discount_amount']??0):Decimal::div(Decimal::mul($sub,(string)($i['discount_rate']??0)),'100');$taxable=Decimal::sub($sub,$disc);if(Decimal::compare($taxable,'0')<0)throw ValidationException::withMessages(['items'=>['Discount cannot exceed line amount.']]);$tax=Decimal::div(Decimal::mul($taxable,$rate),'100');$out[]=['variant_id'=>$v->id,'description'=>$i['description']??$v->product?->name,'unit'=>$i['unit']??null,'quantity'=>Decimal::normalize((string)$i['quantity']),'unit_price'=>Decimal::normalize($price),'discount_type'=>$i['discount_type']??'percentage','discount_rate'=>Decimal::normalize((string)($i['discount_rate']??0)),'discount_amount'=>Decimal::normalize($disc),'tax_code'=>$i['tax_code']??null,'tax_rate'=>Decimal::normalize($rate),'line_subtotal'=>$sub,'tax_amount'=>$tax,'line_total'=>Decimal::add($taxable,$tax)];}return $out;}
 private function totals(array $ls,string $charge):array{$o=['subtotal'=>'0.000000','discount_total'=>'0.000000','tax_total'=>'0.000000','total'=>'0.000000','additional_charges'=>Decimal::normalize($charge)];foreach($ls as $l){$o['subtotal']=Decimal::add($o['subtotal'],$l['line_subtotal']);$o['discount_total']=Decimal::add($o['discount_total'],$l['discount_amount']);$o['tax_total']=Decimal::add($o['tax_total'],$l['tax_amount']);$o['total']=Decimal::add($o['total'],$l['line_total']);}$o['total']=Decimal::add($o['total'],$o['additional_charges']);return $o;}
 public function index(Request $r){$this->auth($r,'sales.manage');$q=SalesQuotation::where('tenant_id',$this->t())->with(['customer','opportunity'])->when($r->filled('company_id'),fn($x)=>$x->where('company_id',$r->company_id))->when($r->filled('branch_id'),fn($x)=>$x->where('branch_id',$r->branch_id))->when($r->filled('search'),fn($x)=>$x->where(fn($s)=>$s->where('number','ilike','%'.$r->search.'%')->orWhereHas('customer',fn($c)=>$c->where('name','ilike','%'.$r->search.'%'))))->when($r->filled('state'),fn($x)=>$x->where('state',$r->state))->latest();return response()->json(['data'=>$q->paginate(min(max($r->integer('per_page',25),10),100))]);}
 public function summary(Request $r){$this->auth($r,'sales.manage');$q=SalesQuotation::where('tenant_id',$this->t())->when($r->filled('company_id'),fn($x)=>$x->where('company_id',$r->company_id));return response()->json(['data'=>['total'=>(clone $q)->count(),'draft'=>(clone $q)->where('state','draft')->count(),'pending_approval'=>(clone $q)->where('approval_status','pending')->count(),'sent'=>(clone $q)->where('state','sent')->count(),'accepted'=>(clone $q)->where('response_status','accepted')->count(),'expired'=>(clone $q)->where('state','expired')->count(),'converted'=>(clone $q)->where('conversion_status','converted')->count()]]);}
 public function show(Request $r,SalesQuotation $q){$this->own($q);$this->auth($r,'sales.manage',$q->company_id,$q->branch_id);return response()->json(['data'=>$q->load(['items.variant.product','customer.contacts','opportunity','versions','approvals','responses','order'])]);}
 public function store(Request $r,SalesNumberService $numbers){$d=$this->input($r);$this->scope($r,$d['company_id'],$d['branch_id']??null);$c=Customer::where('tenant_id',$this->t())->whereKey($d['customer_id'])->firstOrFail();abort_unless($c->company_id===$d['company_id'],422,'Customer is outside the selected company.');if(!empty($d['customer_contact_id']))abort_unless(CustomerContact::where('tenant_id',$this->t())->where('customer_id',$c->id)->whereKey($d['customer_contact_id'])->exists(),422,'Contact does not belong to the customer.');if(!empty($d['opportunity_id']))abort_unless(Opportunity::where('tenant_id',$this->t())->whereKey($d['opportunity_id'])->where('company_id',$d['company_id'])->where('customer_id',$d['customer_id'])->exists(),422,'Opportunity does not match.');if(!empty($d['currency_id']))abort_unless(AccountingCurrency::where('tenant_id',$this->t())->whereKey($d['currency_id'])->exists(),422,'Currency is unavailable.');$ls=$this->lines($d,$d['company_id']);$tot=$this->totals($ls,(string)($d['additional_charges']??0));$q=DB::transaction(function()use($d,$ls,$tot,$r,$numbers){$q=SalesQuotation::create([...$tot,'tenant_id'=>$this->t(),'company_id'=>$d['company_id'],'branch_id'=>$d['branch_id']??null,'customer_id'=>$d['customer_id'],'customer_contact_id'=>$d['customer_contact_id']??null,'opportunity_id'=>$d['opportunity_id']??null,'currency_id'=>$d['currency_id']??null,'price_list_id'=>$d['price_list_id']??null,'assigned_salesperson_id'=>$d['assigned_salesperson_id']??null,'created_by'=>$r->user()->id,'number'=>$numbers->next($this->t(),'quotation'),'quotation_date'=>$d['quotation_date']??now()->toDateString(),'valid_until'=>$d['valid_until']??null,'customer_reference'=>$d['customer_reference']??null,'approval_status'=>'not_required','response_status'=>'pending','conversion_status'=>'not_converted','version_number'=>1,'payment_terms'=>$d['payment_terms']??null,'delivery_terms'=>$d['delivery_terms']??null,'terms_and_conditions'=>$d['terms_and_conditions']??null,'customer_notes'=>$d['customer_notes']??null,'internal_notes'=>$d['internal_notes']??null]);foreach($ls as $l)SalesQuotationItem::create([...$l,'tenant_id'=>$this->t(),'quotation_id'=>$q->id]);$v=SalesQuotationVersion::create(['tenant_id'=>$this->t(),'quotation_id'=>$q->id,'version_number'=>1,'created_by'=>$r->user()->id,'snapshot'=>['items'=>$ls,'totals'=>$tot]]);$q->update(['current_version_id'=>$v->id]);return $q->load('items');});return response()->json(['data'=>$q],201);}
 public function update(Request $r,SalesQuotation $q){$this->own($q);$this->auth($r,'sales.manage',$q->company_id,$q->branch_id);abort_unless($q->state==='draft',422,'Only drafts can be edited.');$d=$this->input($r);$this->scope($r,$d['company_id'],$d['branch_id']??null);$ls=$this->lines($d,$d['company_id']);$tot=$this->totals($ls,(string)($d['additional_charges']??0));DB::transaction(function()use($q,$d,$ls,$tot,$r){$q->update([...$tot,'company_id'=>$d['company_id'],'branch_id'=>$d['branch_id']??null,'customer_id'=>$d['customer_id'],'version_number'=>$q->version_number+1,'valid_until'=>$d['valid_until']??null]);$q->items()->delete();foreach($ls as $l)SalesQuotationItem::create([...$l,'tenant_id'=>$this->t(),'quotation_id'=>$q->id]);$v=SalesQuotationVersion::create(['tenant_id'=>$this->t(),'quotation_id'=>$q->id,'version_number'=>$q->version_number,'created_by'=>$r->user()->id,'revision_reason'=>'Draft revision','snapshot'=>['items'=>$ls,'totals'=>$tot]]);$q->update(['current_version_id'=>$v->id]);});return response()->json(['data'=>$q->fresh('items')]);}
 public function submit(Request $r,SalesQuotation $q){$this->own($q);$this->auth($r,'sales.manage',$q->company_id,$q->branch_id);abort_unless($q->state==='draft',422);$q->update(['approval_status'=>'pending','state'=>'pending_approval']);$this->audit($r,'sales.quotation.submitted',$q);return response()->json(['data'=>$q->fresh()]);}
 public function approve(Request $r,SalesQuotation $q){$this->own($q);$this->auth($r,'sales.approve',$q->company_id,$q->branch_id);abort_unless($q->approval_status==='pending',422);$q->update(['approval_status'=>'approved','state'=>'approved']);SalesQuotationApproval::create(['tenant_id'=>$this->t(),'quotation_id'=>$q->id,'approver_id'=>$r->user()->id,'state'=>'approved','remarks'=>$r->input('remarks'),'decided_at'=>now()]);$this->audit($r,'sales.quotation.approved',$q);return response()->json(['data'=>$q->fresh()]);}
 public function reject(Request $r,SalesQuotation $q){$this->own($q);$this->auth($r,'sales.approve',$q->company_id,$q->branch_id);abort_unless($q->approval_status==='pending',422);$q->update(['approval_status'=>'rejected','state'=>'rejected']);SalesQuotationApproval::create(['tenant_id'=>$this->t(),'quotation_id'=>$q->id,'approver_id'=>$r->user()->id,'state'=>'rejected','remarks'=>$r->input('remarks'),'decided_at'=>now()]);return response()->json(['data'=>$q->fresh()]);}
 public function transition(Request $r,SalesQuotation $q){$state=$r->validate(['state'=>'required|in:sent,accepted,declined,expired,cancelled'])['state'];$this->own($q);$this->auth($r,'sales.manage',$q->company_id,$q->branch_id);if($state==='sent')abort_unless(in_array($q->approval_status,['approved','not_required'],true),422,'Quotation must be approved before sending.');if(in_array($state,['accepted','declined'],true))abort_unless($q->state==='sent'&&(!$q->valid_until||!$q->valid_until->isPast()),422,'Quotation is not eligible for a response.');$q->update(['state'=>$state,'response_status'=>in_array($state,['accepted','declined'],true)?$state:$q->response_status,'accepted_at'=>$state==='accepted'?now():null]);if(in_array($state,['accepted','declined'],true))SalesQuotationResponse::create(['tenant_id'=>$this->t(),'quotation_id'=>$q->id,'version_id'=>$q->current_version_id,'response'=>$state,'source'=>'internal','evidence'=>$r->input('evidence'),'responded_at'=>now(),'responded_by'=>$r->user()->id]);return response()->json(['data'=>$q->fresh()]);}
 public function convert(Request $r,SalesQuotation $q,SalesNumberService $numbers){$this->own($q);$this->auth($r,'sales.manage',$q->company_id,$q->branch_id);$o=DB::transaction(function()use($q,$numbers,$r){$q=SalesQuotation::whereKey($q->id)->lockForUpdate()->with('items')->firstOrFail();if($q->converted_order_id)return SalesOrder::findOrFail($q->converted_order_id);abort_unless($q->state==='accepted'&&$q->response_status==='accepted',422,'Only accepted quotations can be converted.');$o=SalesOrder::create(['tenant_id'=>$this->t(),'company_id'=>$q->company_id,'branch_id'=>$q->branch_id,'currency_id'=>$q->currency_id,'customer_id'=>$q->customer_id,'quotation_id'=>$q->id,'created_by'=>$r->user()->id,'number'=>$numbers->next($this->t(),'order'),'state'=>'draft','subtotal'=>$q->subtotal,'discount_total'=>$q->discount_total,'tax_total'=>$q->tax_total,'total'=>$q->total,'base_total'=>$q->total]);foreach($q->items as $i)SalesOrderItem::create(['tenant_id'=>$this->t(),'sales_order_id'=>$o->id,'variant_id'=>$i->variant_id,'ordered_quantity'=>$i->quantity,'unit_price'=>$i->unit_price,'discount_rate'=>$i->discount_rate,'tax_rate'=>$i->tax_rate,'line_subtotal'=>$i->line_subtotal,'discount_amount'=>$i->discount_amount,'tax_amount'=>$i->tax_amount,'line_total'=>$i->line_total]);$q->update(['conversion_status'=>'converted','converted_order_id'=>$o->id]);return $o->load('items');});return response()->json(['data'=>$o],$o->wasRecentlyCreated?201:200);}
 public function requestRevision(Request $r,SalesQuotation $q){$this->own($q);$this->auth($r,'sales.approve',$q->company_id,$q->branch_id);abort_unless($q->approval_status==='pending',422,'Quotation is not awaiting approval.');$q->update(['approval_status'=>'revision_required','state'=>'draft']);SalesQuotationApproval::create(['tenant_id'=>$this->t(),'quotation_id'=>$q->id,'approver_id'=>$r->user()->id,'state'=>'revision_required','remarks'=>$r->input('remarks'),'decided_at'=>now()]);return response()->json(['data'=>$q->fresh()]);}
 public function send(Request $r,SalesQuotation $q){$this->own($q);$this->auth($r,'sales.manage',$q->company_id,$q->branch_id);$d=$r->validate(['contact_id'=>'required|uuid','subject'=>'nullable|string|max:200','message'=>'required|string|max:5000']);abort_unless(in_array($q->state,['sent','approved'],true)&&in_array($q->approval_status,['approved','not_required'],true),422,'Quotation must be approved before sending.');$contact=CustomerContact::where('tenant_id',$this->t())->where('customer_id',$q->customer_id)->whereKey($d['contact_id'])->firstOrFail();abort_unless($contact->email,422,'Selected contact has no email address.');$communication=SalesQuotationCommunication::create(['tenant_id'=>$this->t(),'quotation_id'=>$q->id,'sent_by'=>$r->user()->id,'recipient'=>$contact->email,'subject'=>$d['subject']??('Sales quotation '.$q->number),'state'=>'queued','queued_at'=>now()]);SendSalesQuotationEmail::dispatch($this->t(),$q->id,$communication->id,$d['message'])->afterCommit();if($q->state==='approved')$q->update(['state'=>'sent']);return response()->json(['data'=>$communication],202);}
 public function communications(Request $r,SalesQuotation $q){$this->own($q);$this->auth($r,'sales.manage',$q->company_id,$q->branch_id);return response()->json(['data'=>$q->communications()->latest()->paginate(min($r->integer('per_page',25),100))]);}
 public function priceLists(Request $r){$this->auth($r,'sales.manage');$q=SalesPriceList::where('tenant_id',$this->t())->where('is_active',true)->with('items')->when($r->filled('company_id'),fn($x)=>$x->where('company_id',$r->company_id));return response()->json(['data'=>$q->paginate(min($r->integer('per_page',25),100))]);}
 public function createPriceList(Request $r){$d=$r->validate(['company_id'=>'required|uuid','name'=>'required|string|max:160','list_type'=>['required',Rule::in(['standard','customer','customer_group','volume','promotional'])],'currency_id'=>'nullable|uuid','customer_id'=>'nullable|uuid','valid_from'=>'nullable|date','valid_until'=>'nullable|date|after_or_equal:valid_from']);$this->scope($r,$d['company_id']);if(!empty($d['currency_id']))abort_unless(AccountingCurrency::where('tenant_id',$this->t())->whereKey($d['currency_id'])->exists(),422);if(!empty($d['customer_id']))abort_unless(Customer::where('tenant_id',$this->t())->where('company_id',$d['company_id'])->whereKey($d['customer_id'])->exists(),422);return response()->json(['data'=>SalesPriceList::create([...$d,'tenant_id'=>$this->t(),'is_active'=>true])],201);}
 public function addPriceListItem(Request $r,SalesPriceList $priceList){abort_unless($priceList->tenant_id===$this->t(),404);$this->scope($r,$priceList->company_id);$d=$r->validate(['variant_id'=>'required|uuid','minimum_quantity'=>'required|numeric|gt:0','unit_price'=>'required|numeric|min:0','valid_from'=>'nullable|date','valid_until'=>'nullable|date|after_or_equal:valid_from']);abort_unless(ProductVariant::where('tenant_id',$this->t())->whereKey($d['variant_id'])->exists(),422,'Product variant is unavailable.');return response()->json(['data'=>SalesPriceListItem::create([...$d,'tenant_id'=>$this->t(),'price_list_id'=>$priceList->id])],201);}
